<script lang="ts">
    import { editorStore } from '@/stores/editor.store'
    import { remoteSpaceMockData, type RemoteFileItem } from '@/mock/sidebar.mock'
    import { ChevronDown, ChevronRight, File, FileText, Folder, FolderOpen, Cloud, BookOpen } from '@lucide/svelte'
    import { cn } from '$lib/clsx/clsx.lib'
    interface Props { activeSpace: 'local' | 'remote' }
    let { activeSpace }: Props = $props()
    let directories = $state<{ path: string; name: string; expanded: boolean; children?: { name: string; path: string; isDirectory: boolean }[] }[]>([])
    let remoteExpanded = $state(new Set<string>())
    function fileIcon(name: string, directory: boolean) { if (directory) return Folder; return /\.(md|txt|docx?)$/i.test(name) ? FileText : File }
    function toggleRemote(path: string) { remoteExpanded = new Set(remoteExpanded.has(path) ? [...remoteExpanded].filter(item => item !== path) : [...remoteExpanded, path]) }
    function openRemote(item: RemoteFileItem) { if (!item.isDirectory) editorStore.setFile(item.path, `# 远程文件内容\n\n这是来自远程空间的文件：${item.path}`) }
    async function addDirectory() { if (window.electron) { const path = await window.electron.openDirectoryDialog(); if (path && !directories.some(item => item.path === path)) directories = [...directories, { path, name: path.split('/').pop() || path, expanded: false }] } }
    async function toggleLocal(directory: typeof directories[number]) { if (!directory.children && window.electron) directory.children = await window.electron.readDirectory(directory.path); directory.expanded = !directory.expanded; directories = [...directories] }
</script>

<aside class="glass-sidebar flex min-h-0 w-64 shrink-0 flex-col border-r border-white/50"><div class="flex h-13 items-center justify-between border-b border-white/50 px-4"><div class="flex items-center gap-2 text-sm font-semibold text-ink-800">{#if activeSpace === 'local'}<BookOpen class="h-4 w-4 text-brand-500" />本地空间{:else}<Cloud class="h-4 w-4 text-brand-500" />远程空间{/if}</div>{#if activeSpace === 'local'}<button type="button" onclick={addDirectory} title="添加本地目录" class="text-ink-500 hover:text-brand-600">+</button>{/if}</div><nav class="min-h-0 flex-1 overflow-auto p-3">
{#if activeSpace === 'local'}{#if directories.length === 0}<button type="button" onclick={addDirectory} class="w-full rounded-lg border border-dashed border-ink-300 px-3 py-6 text-xs text-ink-500 hover:border-brand-300 hover:text-brand-600">添加本地目录</button>{:else}{#each directories as directory}<button type="button" onclick={() => toggleLocal(directory)} class="flex w-full items-center gap-2 rounded-md px-2 py-2 text-left text-xs text-ink-700 hover:bg-white/60">{#if directory.expanded}<FolderOpen class="h-4 w-4 text-brand-500" />{:else}<Folder class="h-4 w-4 text-ink-400" />{/if}<span class="flex-1 truncate">{directory.name}</span>{#if directory.expanded}<ChevronDown class="h-3.5 w-3.5" />{:else}<ChevronRight class="h-3.5 w-3.5" />{/if}</button>{#if directory.expanded}{#each directory.children ?? [] as item}{@const Icon = fileIcon(item.name, item.isDirectory)}<button type="button" onclick={() => !item.isDirectory && editorStore.setFile(item.path, '')} class="ml-4 flex w-[calc(100%-1rem)] items-center gap-2 rounded-md px-2 py-1.5 text-left text-xs text-ink-600 hover:bg-white/60"><Icon class="h-3.5 w-3.5 text-ink-400" /><span class="truncate">{item.name}</span></button>{/each}{/if}{/each}{/if}
{:else}{#each remoteSpaceMockData as item}{@const Icon = fileIcon(item.name, item.isDirectory)}<button type="button" onclick={() => item.isDirectory ? toggleRemote(item.path) : openRemote(item)} class="flex w-full items-center gap-2 rounded-md px-2 py-2 text-left text-xs text-ink-700 hover:bg-white/60">{#if item.isDirectory}{#if remoteExpanded.has(item.path)}<FolderOpen class="h-4 w-4 text-brand-500" />{:else}<Folder class="h-4 w-4 text-ink-400" />{/if}{:else}<Icon class="h-4 w-4 text-ink-400" />{/if}<span class="flex-1 truncate">{item.name}</span>{#if item.isDirectory}{#if remoteExpanded.has(item.path)}<ChevronDown class="h-3.5 w-3.5" />{:else}<ChevronRight class="h-3.5 w-3.5" />{/if}{/if}</button>{#if item.isDirectory && remoteExpanded.has(item.path)}{#each item.children ?? [] as child}{@const ChildIcon = fileIcon(child.name, child.isDirectory)}<button type="button" onclick={() => child.isDirectory ? toggleRemote(child.path) : openRemote(child)} class="ml-4 flex w-[calc(100%-1rem)] items-center gap-2 rounded-md px-2 py-1.5 text-left text-xs text-ink-600 hover:bg-white/60"><ChildIcon class="h-3.5 w-3.5 text-ink-400" /><span class="truncate">{child.name}</span></button>{/each}{/if}{/each}{/if}</nav></aside>
